"""History signals: how often, and how badly, the files in a change have been touched lately."""

from __future__ import annotations

import re
from dataclasses import dataclass, field
from datetime import datetime, timedelta

from .gitops import GitError, run_git

FIX_SUBJECT = re.compile(
    r"(?i)\b(fix(?:es|ed|ing)?|bug(?:fix)?|hotfix|regression|crash(?:es)?|broken|incident|patch)\b"
)
MAX_COMMITS = 4000


@dataclass
class FileHistory:
    commits: int = 0
    fixes: int = 0
    authors: set[str] = field(default_factory=set)

    @property
    def fix_ratio(self) -> float:
        return self.fixes / self.commits if self.commits else 0.0


@dataclass
class History:
    days: int
    window_start: str
    files: dict[str, FileHistory]

    def get(self, path: str) -> FileHistory | None:
        return self.files.get(path)


def collect(repo, paths: list[str], since_ref: str, days: int = 90) -> History | None:
    """Look back `days` from `since_ref`'s commit date, so results do not depend on today's date.

    Returns None when there is nothing to look at (no paths) or the history is unreachable.
    """
    if not paths:
        return None
    try:
        stamp = run_git(repo, "show", "-s", "--format=%cI", since_ref).strip()
        anchor = datetime.fromisoformat(stamp)
    except (GitError, ValueError):
        return None
    start = (anchor - timedelta(days=days)).isoformat()

    # Paths go over stdin: a big change would overflow the command line on Windows.
    stdin = f"{since_ref}\n--\n" + "\n".join(paths) + "\n"
    fmt = "\x1e%H\x1f%an\x1f%s"
    try:
        out = run_git(
            repo, "log", "--no-color", "--no-merges", "--no-renames", f"--since={start}",
            f"--max-count={MAX_COMMITS}", f"--format={fmt}", "--name-only", "--stdin",
            stdin=stdin,
        )  # fmt: skip
    except GitError:
        return None

    files: dict[str, FileHistory] = {}
    for block in out.split("\x1e"):
        block = block.strip("\n")
        if not block:
            continue
        head, _, names = block.partition("\n")
        _sha, author, subject = (head.split("\x1f") + ["", "", ""])[:3]
        is_fix = bool(FIX_SUBJECT.search(subject))
        for name in names.split("\n"):
            name = name.strip()
            if not name:
                continue
            fh = files.setdefault(name, FileHistory())
            fh.commits += 1
            fh.authors.add(author)
            if is_fix:
                fh.fixes += 1
    return History(days=days, window_start=start, files=files)

files.changerisk/paths.py:
"""Path matching and the "what kind of file is this" questions the rules keep asking."""

from __future__ import annotations

import re
from collections.abc import Iterable
from functools import lru_cache
from pathlib import PurePosixPath


@lru_cache(maxsize=512)
def compile_glob(pattern: str) -> re.Pattern[str]:
    """Translate a gitignore-flavoured glob into a regex.

    `**` crosses directories, `*` and `?` do not. A pattern without a slash matches the
    file name at any depth, a trailing slash means "everything under this directory".
    """
    pat = pattern.strip().replace("\\", "/")
    anchored = pat.startswith("/")
    pat = pat.lstrip("/")
    if pat.endswith("/"):
        pat += "**"
    floating = "/" not in pat.rstrip("*") and not anchored

    out: list[str] = []
    i = 0
    while i < len(pat):
        c = pat[i]
        if c == "*":
            if pat[i : i + 3] == "**/":
                out.append("(?:.*/)?")
                i += 3
                continue
            if pat[i : i + 2] == "**":
                out.append(".*")
                i += 2
                continue
            out.append("[^/]*")
        elif c == "?":
            out.append("[^/]")
        else:
            out.append(re.escape(c))
        i += 1
    body = "".join(out)
    prefix = r"(?:.*/)?" if floating else ""
    return re.compile(rf"^{prefix}{body}$", re.IGNORECASE)


def matches_any(path: str, patterns: Iterable[str]) -> bool:
    return any(compile_glob(p).match(path) for p in patterns)


# ---------------------------------------------------------------------------
# Built-in knowledge about file kinds
# ---------------------------------------------------------------------------

TEST_DIRS = {
    "test", "tests", "__tests__", "spec", "specs", "e2e", "integration_tests", "unit_tests",
    "cypress", "playwright",
}  # fmt: skip
TEST_NAME = re.compile(
    r"""(?ix)
    ^(?:test_.*\.py | .*_test\.(?:py|go|rb|rs|exs?) | conftest\.py
     | .*\.(?:test|spec)\.[cm]?[jt]sx? | .*_spec\.rb
     | .*Tests?\.(?:java|kt|cs|swift|scala) | .*IT\.java | .*Test\.php)$
    """
)

DOC_EXTS = {".md", ".mdx", ".rst", ".txt", ".adoc"}
DOC_NAMES = {"license", "licence", "notice", "authors", "contributors", "changelog", "codeowners"}

LOCKFILES = {
    "package-lock.json", "npm-shrinkwrap.json", "yarn.lock", "pnpm-lock.yaml", "bun.lockb",
    "poetry.lock", "uv.lock", "pdm.lock", "pipfile.lock", "cargo.lock", "go.sum",
    "gemfile.lock", "composer.lock", "packages.lock.json", "gradle.lockfile",
}  # fmt: skip
GENERATED_DIRS = {
    "node_modules", "vendor", "dist", "build", ".next", "__generated__", "generated",
    "__snapshots__", "coverage", "target", "third_party",
}  # fmt: skip
GENERATED_NAME = re.compile(
    r"(?i)(?:\.min\.(?:js|css)|\.map|\.snap|_pb2(?:_grpc)?\.pyi?|\.pb\.go|\.generated\.\w+|\.designer\.cs)$"
)

LANGUAGES = {
    ".py": "python", ".pyi": "python",
    ".js": "javascript", ".jsx": "javascript", ".mjs": "javascript", ".cjs": "javascript",
    ".ts": "typescript", ".tsx": "typescript",
    ".go": "go", ".java": "java", ".kt": "kotlin", ".scala": "scala", ".cs": "csharp",
    ".rb": "ruby", ".php": "php", ".rs": "rust", ".swift": "swift",
    ".c": "c", ".h": "c", ".cc": "cpp", ".cpp": "cpp", ".hpp": "cpp",
    ".sh": "shell", ".bash": "shell", ".ps1": "powershell",
    ".sql": "sql", ".tf": "terraform",
}  # fmt: skip
SOURCE_LANGS = set(LANGUAGES.values()) - {"shell", "powershell", "sql", "terraform"}

CONFIG_DIRS = {
    "config", "configs", "conf", "settings", "deploy", "deployment", "k8s", "kubernetes",
    "helm", "charts", "infra", "infrastructure", "environments", "envs", "terraform", "ansible",
}  # fmt: skip
CONFIG_NAME = re.compile(
    r"""(?ix)
    ^(?: \.env(?:\..+)?
       | settings(?:_\w+)?\.py | config(?:uration)?\.(?:py|js|ts|json|ya?ml|toml|rb)
       | application(?:-[\w.]+)?\.(?:ya?ml|properties) | appsettings(?:\.[\w]+)?\.json
       | docker-compose(?:\.[\w-]+)?\.ya?ml | compose(?:\.[\w-]+)?\.ya?ml | dockerfile(?:\.[\w.-]+)?
       | .*\.(?:tf|tfvars|ini|cfg|conf|properties)
       | nginx.*\.conf | procfile | \.npmrc | \.pypirc | pytest\.ini | tox\.ini | \.coveragerc
       | values(?:[-.][\w.-]+)?\.ya?ml | .*\.config\.[cm]?[jt]s )$
    """
)
ENV_TEMPLATE = re.compile(r"(?i)\.(?:example|sample|template|dist|defaults?)$")

PIPELINE_PATTERNS = (
    ".github/workflows/*.yml", ".github/workflows/*.yaml", ".github/actions/**",
    ".gitlab-ci.yml", ".gitlab/**/*.yml", "Jenkinsfile*", "azure-pipelines*.yml",
    ".circleci/**", ".travis.yml", "bitbucket-pipelines.yml", ".drone.yml", "cloudbuild.yaml",
)  # fmt: skip

MIGRATION_DIR = re.compile(
    r"(?i)(?:^|/)(?:migrations?|alembic/versions|db/migrate|flyway|liquibase|prisma/migrations)/"
)

MANIFESTS = (
    "package.json", "requirements*.txt", "constraints*.txt", "pyproject.toml", "Pipfile",
    "Cargo.toml", "go.mod", "Gemfile", "composer.json", "pom.xml", "build.gradle",
    "build.gradle.kts", "*.csproj", "Package.swift",
)  # fmt: skip

CONTAINER_DIRS = {"src", "lib", "app", "apps", "packages", "services", "internal", "pkg", "cmd"}


class Classifier:
    """Answers questions about a path, with user-supplied globs layered on the built-ins."""

    def __init__(
        self,
        *,
        tests: Iterable[str] = (),
        generated: Iterable[str] = (),
        sensitive: Iterable[str] = (),
        docs: Iterable[str] = (),
    ) -> None:
        self.extra_tests = tuple(tests)
        self.extra_generated = tuple(generated)
        self.sensitive = tuple(sensitive)
        self.extra_docs = tuple(docs)

    @staticmethod
    def _parts(path: str) -> tuple[list[str], str]:
        p = PurePosixPath(path)
        return [x.lower() for x in p.parts[:-1]], p.name

    def language(self, path: str) -> str | None:
        return LANGUAGES.get(PurePosixPath(path).suffix.lower())

    def is_test(self, path: str) -> bool:
        dirs, name = self._parts(path)
        if matches_any(path, self.extra_tests):
            return True
        return any(d in TEST_DIRS for d in dirs) or bool(TEST_NAME.match(name))

    def is_doc(self, path: str) -> bool:
        dirs, name = self._parts(path)
        if matches_any(path, self.extra_docs):
            return True
        stem = name.rsplit(".", 1)[0].lower()
        if PurePosixPath(name).suffix.lower() in DOC_EXTS:
            return True
        if stem in DOC_NAMES:
            return True
        return bool(dirs) and dirs[0] in {"docs", "doc", "documentation"}

    def is_lockfile(self, path: str) -> bool:
        name = PurePosixPath(path).name.lower()
        return name in LOCKFILES or name.endswith(".lock")

    def is_generated(self, path: str) -> bool:
        dirs, name = self._parts(path)
        if matches_any(path, self.extra_generated):
            return True
        if self.is_lockfile(path) or GENERATED_NAME.search(name):
            return True
        return any(d in GENERATED_DIRS for d in dirs)

    def is_pipeline(self, path: str) -> bool:
        return matches_any(path, PIPELINE_PATTERNS)

    def is_manifest(self, path: str) -> bool:
        return matches_any(path, MANIFESTS)

    def is_migration(self, path: str) -> bool:
        name = PurePosixPath(path).name.lower()
        if MIGRATION_DIR.search(path):
            return not self.is_doc(path)
        return name in {"schema.prisma", "schema.rb", "structure.sql"}

    def is_config(self, path: str) -> bool:
        """Configuration that changes behaviour without changing code.

        Pipeline files and dependency manifests have their own rules and are left out, except
        for the Python tool configs that live inside a manifest.
        """
        if self.is_pipeline(path) or self.is_generated(path) or self.is_test(path):
            return False
        if self.is_migration(path):
            return False
        dirs, name = self._parts(path)
        if ENV_TEMPLATE.search(name) and name.lower().startswith(".env"):
            return False
        if name.lower() in {"pyproject.toml", "setup.cfg"}:
            return True
        if self.is_manifest(path):
            return False
        if CONFIG_NAME.match(name):
            return True
        ext = PurePosixPath(name).suffix.lower()
        return ext in {".yml", ".yaml", ".toml", ".json", ".ini", ".xml"} and any(
            d in CONFIG_DIRS for d in dirs
        )

    def is_source(self, path: str) -> bool:
        if self.is_test(path) or self.is_generated(path) or self.is_migration(path):
            return False
        lang = self.language(path)
        return lang in SOURCE_LANGS

    def is_sensitive_path(self, path: str) -> bool:
        return matches_any(path, self.sensitive)

    def area(self, path: str) -> str:
        """The module a file belongs to, for judging how widely a change spreads."""
        parts = PurePosixPath(path).parts
        if len(parts) == 1:
            return "(root)"
        if parts[0].lower() in CONTAINER_DIRS and len(parts) > 2:
            return f"{parts[0]}/{parts[1]}"
        return parts[0]


_COMMENT_PREFIXES = {
    "hash": ("#",),
    "slash": ("//", "/*", "*"),
    "dash": ("--",),
}
_HASH_LANGS = {"python", "ruby", "shell", "powershell", "terraform", None}
_SLASH_LANGS = {
    "javascript", "typescript", "go", "java", "kotlin", "scala", "csharp", "php", "rust",
    "swift", "c", "cpp", "terraform",
}  # fmt: skip


def is_comment(text: str, language: str | None) -> bool:
    """Cheap comment check so pattern rules do not fire on commented-out code."""
    s = text.lstrip()
    if not s:
        return False
    if language in _HASH_LANGS and s.startswith("#"):
        return True
    if language in _SLASH_LANGS and s.startswith(_COMMENT_PREFIXES["slash"]):
        return True
    return language == "sql" and s.startswith("--")

files.changerisk/remote.py:
"""Getting a change from somewhere other than a local repository.

Two sources: a unified diff someone pasted, and a public GitHub pull request. This is the input
side of the hosted dashboard, so it treats everything as untrusted: strict URL parsing, a fixed
list of hosts it will talk to, size and line-length caps, and error messages written for the person
who typed the input.
"""

from __future__ import annotations

import contextlib
import json
import os
import re
import time
import urllib.error
import urllib.request
from collections.abc import Callable, Mapping
from dataclasses import dataclass
from typing import Any
from urllib.parse import quote, urlsplit

from .config import CONFIG_NAMES, Config, ConfigError, parse_config
from .diffparse import parse_diff
from .gitops import GitError, validate_ref
from .models import ChangeSet, CommitInfo
from .paths import Classifier

API_HOST = "api.github.com"
RAW_HOST = "raw.githubusercontent.com"
ALLOWED_HOSTS = {API_HOST, RAW_HOST}

MAX_DIFF_BYTES = int(os.environ.get("CHANGERISK_MAX_DIFF_KB", "2048")) * 1024
MAX_LINE_CHARS = 2000  # longer lines are cut: they only slow the pattern rules down
MAX_FILES = 1500
MAX_CONFIG_BYTES = 64 * 1024
TIMEOUT = 15

_OWNER = r"[A-Za-z0-9](?:[A-Za-z0-9-]{0,37}[A-Za-z0-9])?"
_REPO = r"[A-Za-z0-9._-]{1,100}"
_PR_URL = re.compile(
    rf"^(?:https?://)?(?:www\.)?github\.com/({_OWNER})/({_REPO})/pull/(\d{{1,7}})(?:[/?#].*)?$"
)
_PR_SHORT = re.compile(rf"^({_OWNER})/({_REPO})#(\d{{1,7}})$")
_COMPARE_URL = re.compile(
    rf"^(?:https?://)?(?:www\.)?github\.com/({_OWNER})/({_REPO})/compare/([^\s?#]{{1,200}})\.\.\.([^\s?#]{{1,200}})$"
)


class SourceError(ValueError):
    """The input could not be turned into a change. The message is meant to be shown as is."""

    def __init__(self, message: str, status: int = 400) -> None:
        super().__init__(message)
        self.status = status


@dataclass(frozen=True)
class PullRef:
    owner: str
    repo: str
    number: int

    @property
    def label(self) -> str:
        return f"{self.owner}/{self.repo}#{self.number}"


@dataclass(frozen=True)
class CompareRef:
    owner: str
    repo: str
    base: str
    head: str

    @property
    def label(self) -> str:
        return f"{self.owner}/{self.repo}@{self.base}...{self.head}"


def parse_source(text: str) -> PullRef | CompareRef:
    text = (text or "").strip()
    if not text or len(text) > 400:
        raise SourceError(_HINT)
    m = _PR_URL.match(text) or _PR_SHORT.match(text)
    if m:
        return PullRef(m.group(1), m.group(2), int(m.group(3)))
    m = _COMPARE_URL.match(text)
    if m:
        base, head = m.group(3), m.group(4)
        try:
            validate_ref(base)
            validate_ref(head)
        except GitError:
            raise SourceError("Those branch names in the compare link are not usable.") from None
        return CompareRef(m.group(1), m.group(2), base, head)
    raise SourceError(_HINT)


_HINT = (
    "Enter a public GitHub pull request, such as https://github.com/owner/repo/pull/123 "
    "or owner/repo#123. A compare link (github.com/owner/repo/compare/main...branch) also works."
)


# --- diffs ---------------------------------------------------------------------


def changes_from_diff(text: str, *, label: str = "pasted diff") -> ChangeSet:
    """Turn unified diff text (as `git diff` or a pull request's .diff prints it) into a ChangeSet."""
    if not text or not text.strip():
        raise SourceError("There is no diff to analyse. Paste the output of `git diff`.")
    if len(text.encode("utf-8", errors="ignore")) > MAX_DIFF_BYTES:
        raise SourceError(
            f"That diff is larger than {MAX_DIFF_BYTES // 1024} KB. Analyse a smaller change, "
            "or run ChangeRisk locally, which has no size limit.",
            413,
        )
    text = text.lstrip("﻿")
    if "diff --git " not in text:
        raise SourceError(
            "That does not look like a git diff. Paste the output of `git diff`, "
            "or the .diff of a pull request."
        )
    files = parse_diff(text)
    if not files:
        raise SourceError("No changed files were found in that diff.")
    truncated = False
    if len(files) > MAX_FILES:
        files, truncated = files[:MAX_FILES], True
    for fc in files:
        for hunk in fc.hunks:
            for line in hunk.lines:
                if len(line.text) > MAX_LINE_CHARS:
                    line.text = line.text[:MAX_LINE_CHARS]
    return ChangeSet(
        files=files, base="(pasted)", head="diff", mode="diff", repo_name=label, truncated=truncated
    )


# --- GitHub ---------------------------------------------------------------------

Transport = Callable[[str, Mapping[str, str]], tuple[int, Mapping[str, str], bytes]]


class _SameHostRedirects(urllib.request.HTTPRedirectHandler):
    """Follow redirects only to hosts we already trust, so a response cannot aim us elsewhere."""

    def redirect_request(self, req, fp, code, msg, headers, newurl):  # type: ignore[override]
        if urlsplit(newurl).hostname not in ALLOWED_HOSTS:
            raise SourceError("GitHub redirected to an address this server will not follow.", 502)
        return super().redirect_request(req, fp, code, msg, headers, newurl)


def require_trusted(url: str) -> None:
    """Refuse anything but HTTPS to the two GitHub hosts."""
    if urlsplit(url).hostname not in ALLOWED_HOSTS or not url.startswith("https://"):
        raise SourceError("Refusing to contact that address.", 502)


def _urllib_transport(max_bytes: int) -> Transport:
    opener = urllib.request.build_opener(_SameHostRedirects)

    def fetch(url: str, headers: Mapping[str, str]) -> tuple[int, Mapping[str, str], bytes]:
        require_trusted(url)
        req = urllib.request.Request(url, headers=dict(headers))
        try:
            with opener.open(req, timeout=TIMEOUT) as resp:
                body = resp.read(max_bytes + 1)
                return resp.status, dict(resp.headers.items()), body
        except urllib.error.HTTPError as exc:
            return exc.code, dict(exc.headers.items()) if exc.headers else {}, exc.read(65536)
        except (urllib.error.URLError, TimeoutError, OSError):
            raise SourceError("Could not reach GitHub. Try again in a moment.", 502) from None

    return fetch


class GitHub:
    def __init__(self, token: str | None = None, transport: Transport | None = None) -> None:
        self.token = token
        self._transport = transport or _urllib_transport(MAX_DIFF_BYTES)
        self.remaining: int | None = None  # from the last response's rate-limit header

    def _headers(self, accept: str) -> dict[str, str]:
        headers = {
            "Accept": accept,
            "User-Agent": "changerisk",
            "X-GitHub-Api-Version": "2022-11-28",
        }
        if self.token:
            headers["Authorization"] = f"Bearer {self.token}"
        return headers

    def _get(self, path: str, accept: str = "application/vnd.github+json") -> bytes:
        status, headers, body = self._transport(f"https://{API_HOST}{path}", self._headers(accept))
        lower = {k.lower(): v for k, v in headers.items()}
        if "x-ratelimit-remaining" in lower:
            with contextlib.suppress(ValueError):
                self.remaining = int(lower["x-ratelimit-remaining"])
        if status == 200:
            if len(body) > MAX_DIFF_BYTES:
                raise SourceError(
                    "GitHub returned more than this server will analyse. Pick a smaller change.",
                    413,
                )
            return body
        raise _api_error(status, lower, body)

    def json(self, path: str) -> Any:
        body = self._get(path)  # may raise SourceError, which is itself a ValueError
        try:
            return json.loads(body)
        except ValueError:
            raise SourceError("GitHub sent a reply that could not be read.", 502) from None

    def diff(self, path: str) -> str:
        return self._get(path, "application/vnd.github.v3.diff").decode("utf-8", errors="replace")

    def raw(self, owner: str, repo: str, ref: str, path: str) -> str | None:
        """A file at a commit, from the raw host (which does not count against the API quota)."""
        url = f"https://{RAW_HOST}/{owner}/{repo}/{quote(ref, safe='')}/{quote(path)}"
        status, _, body = self._transport(url, {"User-Agent": "changerisk"})
        if status == 200 and len(body) <= MAX_CONFIG_BYTES:
            return body.decode("utf-8", errors="replace")
        return None


def _api_error(status: int, headers: Mapping[str, str], body: bytes) -> SourceError:
    text = body[:400].decode("utf-8", errors="replace").lower()
    if status == 404:
        return SourceError(
            "GitHub could not find that. Only public repositories can be analysed, "
            "and the pull request or branch has to exist.",
            404,
        )
    if status in (403, 429) and (
        "rate limit" in text or headers.get("x-ratelimit-remaining") == "0"
    ):
        wait = ""
        reset = headers.get("x-ratelimit-reset")
        if reset and reset.isdigit():
            minutes = round((int(reset) - time.time()) / 60)
            if minutes > 60:  # GitHub's window is an hour, so this clock is wrong; do not repeat it
                wait = " It resets within the hour."
            else:
                minutes = max(1, minutes)
                wait = f" It resets in about {minutes} minute{'s' if minutes != 1 else ''}."
        return SourceError(
            "GitHub's limit on anonymous requests has been reached." + wait + " "
            "You can paste the diff instead, which does not use GitHub.",
            429,
        )
    if status in (406, 422) and ("too_large" in text or "too large" in text or "exceeds" in text):
        return SourceError(
            "GitHub will not produce a diff for a change this large. Pick a smaller one, "
            "or run ChangeRisk locally.",
            413,
        )
    return SourceError(f"GitHub answered with status {status}.", 502)


def _config_from(gh: GitHub, owner: str, repo: str, ref: str) -> tuple[Config, str | None]:
    """The repository's own settings at `ref` (the base), or the defaults. Never raises."""
    from .rules.base import option_defaults

    for name in CONFIG_NAMES:
        text = gh.raw(owner, repo, ref, name)
        if text:
            try:
                import tomllib

                return parse_config(tomllib.loads(text), None, option_defaults()), name
            except (ConfigError, ValueError):
                return Config(), None  # a broken config should not stop an analysis
    return Config(), None


def changes_from_pull(gh: GitHub, ref: PullRef) -> tuple[ChangeSet, Config, list[str]]:
    base = f"/repos/{ref.owner}/{ref.repo}/pulls/{ref.number}"
    pr = gh.json(base)
    diff = gh.diff(base)
    changes = changes_from_diff(diff, label=f"{ref.owner}/{ref.repo}")
    notes = [
        "Analysed from the pull request's diff on GitHub. History signals need a local clone "
        "and were skipped."
    ]

    commits: list[CommitInfo] = []
    try:
        for c in gh.json(f"{base}/commits?per_page=100"):
            info = c.get("commit", {})
            author = info.get("author") or {}
            commits.append(
                CommitInfo(
                    sha=str(c.get("sha", "")),
                    author=str(author.get("name", "")),
                    date=str(author.get("date", "")),
                    subject=str(info.get("message", "")).split("\n", 1)[0],
                )
            )
    except SourceError:
        notes.append("The commit list could not be loaded.")

    head_sha = pr["head"]["sha"]
    base_sha = pr["base"]["sha"]
    needs_tree = any(Classifier().is_manifest(f.path) for f in changes.files)
    if needs_tree:
        try:
            tree = gh.json(f"/repos/{ref.owner}/{ref.repo}/git/trees/{head_sha}?recursive=1")
            changes.repo_files = frozenset(
                t["path"] for t in tree.get("tree", []) if t.get("type") == "blob"
            )
            if tree.get("truncated"):
                notes.append(
                    "The repository is too large to list, so lockfile checks may be incomplete."
                )
        except SourceError:
            notes.append(
                "The repository's file list could not be loaded, so lockfile checks were skipped."
            )

    config, config_name = _config_from(gh, ref.owner, ref.repo, base_sha)
    if config_name:
        notes.append(f"Using {config_name} from the pull request's base commit.")

    changes.mode = "pr"
    changes.base = pr["base"]["ref"]
    changes.head = pr["head"].get("label") or pr["head"]["ref"]
    changes.base_sha, changes.head_sha, changes.merge_base = base_sha, head_sha, base_sha
    changes.commits = commits
    changes.source = {
        "type": "github",
        "url": pr.get("html_url", ""),
        "title": str(pr.get("title", ""))[:300],
        "number": ref.number,
        "author": (pr.get("user") or {}).get("login", ""),
        "state": "merged" if pr.get("merged_at") else pr.get("state", ""),
        "label": ref.label,
    }
    return changes, config, notes


def changes_from_compare(gh: GitHub, ref: CompareRef) -> tuple[ChangeSet, Config, list[str]]:
    path = f"/repos/{ref.owner}/{ref.repo}/compare/{quote(ref.base, safe='/')}...{quote(ref.head, safe='/:')}"
    diff = gh.diff(path)
    changes = changes_from_diff(diff, label=f"{ref.owner}/{ref.repo}")
    config, config_name = _config_from(gh, ref.owner, ref.repo, ref.base)
    notes = [
        "Analysed from a GitHub compare view. History signals and lockfile checks need a local "
        "clone and were skipped."
    ]
    if config_name:
        notes.append(f"Using {config_name} from {ref.base}.")
    changes.mode = "pr"
    changes.base, changes.head = ref.base, ref.head
    changes.source = {
        "type": "github",
        "url": f"https://github.com/{ref.owner}/{ref.repo}/compare/{ref.base}...{ref.head}",
        "title": "",
        "label": ref.label,
    }
    return changes, config, notes


MAX_LABEL_CHARS = 60


def _diff_label(label: object) -> str:
    """The name a diff is shown under. Optional, so a page can call a built-in example by its title."""
    if label is None:
        return "pasted diff"
    if not isinstance(label, str) or not label.strip() or not label.isprintable():
        raise SourceError("The diff's name has to be plain text.")
    if len(label) > MAX_LABEL_CHARS:
        raise SourceError(f"The diff's name has to be at most {MAX_LABEL_CHARS} characters.")
    return label.strip()


def load_source(gh: GitHub, source: dict[str, Any]) -> tuple[ChangeSet, Config, list[str]]:
    """Resolve a request's `source` object into a change, the config to use, and report notes."""
    kind = source.get("type")
    if kind == "diff":
        text = source.get("text")
        if not isinstance(text, str):
            raise SourceError("The diff has to be text.")
        label = _diff_label(source.get("label"))
        changes = changes_from_diff(text, label=label)
        changes.source = {"type": "diff", "label": label}
        return (
            changes,
            Config(),
            [
                "Analysed from a pasted diff. Lockfile and history checks need the repository "
                "and were skipped."
            ],
        )
    if kind == "github":
        url = source.get("url")
        if not isinstance(url, str):
            raise SourceError(_HINT)
        parsed = parse_source(url)
        if isinstance(parsed, PullRef):
            return changes_from_pull(gh, parsed)
        return changes_from_compare(gh, parsed)
    raise SourceError("The source has to be a pasted diff or a GitHub pull request.")

